var l=[{title:`Концентрична дія`,text:`М’яз створює силу, коли загалом вкорочується. У згинанні рук на біцепс згиначі ліктя вкорочуються, коли вага піднімається. Під час підйому з присіду кілька розгиначів стегна й коліна працюють, щоб підняти вас. «Концентрична» описує те, що робить м’яз, а це не завжди збігається з тим, чи схожа вправа на рух угору.`},{title:`Ексцентрична дія`,text:`М’яз створює силу, коли подовжується під навантаженням, часто гальмуючи рух. Опускання гантелі в згинанні чи сідання в присід використовує ексцентричну дію головних робочих м’язів. Ця фаза допомагає силі та росту м’язів, але дуже незвична ексцентрична робота може спричинити сильну болючість. Нарощуйте її поступово і не перебільшуйте навмисно кожну фазу опускання.`},{title:`Ізометрична дія`,text:`М’яз створює силу без помітної зміни загальної довжини чи кута суглоба, який він контролює. Планки та стілець біля стіни є чіткими прикладами, а м’язи тулуба працюють приблизно ізометрично, коли ви утримуєте важке перенесення. Утримання під одним кутом не є ідеальною заміною руху в усій амплітуді.`},{title:`Ролі змінюються залежно від завдання`,text:`Агоніст: це головний учасник задуманої дії, а антагоніст протидіє їй або допомагає регулювати рух. Синергісти допомагають, а стабілізатори контролюють суглоби чи сегменти тіла. У віджиманні штовхають груди й трицепси, а м’язи тулуба тримають вас у лінії. Ці ролі залежать від руху, тож у м’яза немає постійної мітки.`},{title:`Застосування на практиці`,text:`Опускайтеся з контролем, уникайте неконтрольованого відскоку та штовхайте чи тягніть в амплітуді, яку ви контролюєте. Утримання на час корисні, коли завдання не потребує руху, а динамічні повторення корисні, коли ви хочете сили в русі. У TrainUp кожна вправа задана повтореннями або часом утримання, а таймер утримання відстежує ваші утримання. Нотатки про техніку й темп допомагають робити хороші повторення, але повільніший рух не завжди дає швидші результати.`}];var i=[{label:`Позиційна заява ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Огляд механізмів гіпертрофії м’язів`,url:`https://pubmed.ncbi.nlm.nih.gov/37382939/`}];var n={sections:l,sources:i};export{n as default,l as sections,i as sources};